@startuml
class Property {
  +code : string
  +address : string
  +zipCode : string
  +city : string
  +area : int
  +getDetails() : string
}

class Garage extends Property {
  +parkingSpaces : int
}

class Apartment extends Property {
  +rooms : int
  +bathrooms : int
}

class Villa extends Apartment {
  +gardenSize : int
}

class Agency {
  +search(key : string)
}

Agency "1" -- "*" Property : manages
@enduml

